import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, FancyArrowPatch
from paper_plot_style import COLORS, save, FIG_DIR

# Diagram data are the pre-training profiles recorded in DATA_GUIDE.md and
# generated by _s7_sweep_contestability.py; no result values are invented here.
cross = [0.837, 0.912, 0.989, 0.993, 0.855]
coloc = [0.921, 0.823, 0.989, 0.996, 0.991]

fig = plt.figure(figsize=(6.9, 3.55))
ax = fig.add_axes([0.02, 0.48, 0.96, 0.48])
ax.set_xlim(0, 1); ax.set_ylim(0, 1); ax.axis('off')
boxes = [
    (0.02, 0.23, 0.25, 0.55, 'Mission queue', 'service + bearing\ndeadline window', COLORS['blue']),
    (0.375, 0.23, 0.25, 0.55, '2 jammer team', '+60° / −60°\n63-token budget', COLORS['red']),
    (0.73, 0.23, 0.25, 0.55, '2 radar team', '+20° / −20°\nbeam + service', COLORS['green']),
]
for x, y, w, h, title, text, color in boxes:
    patch = FancyBboxPatch((x,y), w,h, boxstyle='round,pad=0.012,rounding_size=0.015',
                           facecolor='white', edgecolor=color, linewidth=1.5)
    ax.add_patch(patch)
    ax.text(x+w/2, y+h-0.12, title, ha='center', va='center', fontsize=10, weight='bold', color=color)
    ax.text(x+w/2, y+0.30, text, ha='center', va='center', fontsize=9, color=COLORS['black'])
for x1, x2, label in [(0.27,0.375,'deadline\ncredit'), (0.625,0.73,'bearing-aware\nJNR')]:
    ax.add_patch(FancyArrowPatch((x1,0.50),(x2,0.50),arrowstyle='-|>',mutation_scale=12,
                                 linewidth=1.2,color=COLORS['grey']))
    ax.text((x1+x2)/2,0.62,label,ha='center',va='bottom',fontsize=7.5,color=COLORS['grey'])
ax.text(0.5, 0.96, 'Task-level adversarial co-adaptation', ha='center', va='top', fontsize=11, weight='bold')

ax2 = fig.add_axes([0.09, 0.15, 0.40, 0.22])
az = list(range(5))
ax2.plot(az, cross, 'o-', color=COLORS['red'], label='cross-fire')
ax2.plot(az, coloc, 's--', color=COLORS['blue'], label='co-located')
ax2.axhspan(0.05, 0.95, color=COLORS['yellow'], alpha=0.12, label='contestable band')
ax2.set_xlabel('Mission azimuth sector'); ax2.set_ylabel('Best-response $p_{detect}$')
ax2.set_xticks(az); ax2.set_ylim(0,1.05); ax2.legend(frameon=False, fontsize=6.8, loc='lower left')
ax2.grid(alpha=.25)
ax3 = fig.add_axes([0.59, 0.15, 0.32, 0.22])
ax3.axis('off')
ax3.text(0.5,0.90,'Pre-training gate',ha='center',weight='bold',fontsize=9)
ax3.text(0.5,0.62,'≥3/5 contestable\nmin $p$ > 0.02\nmax $p$ > 0.8',ha='center',va='center',fontsize=9)
ax3.text(0.5,0.12,'Prediction is made before PPO updates',ha='center',fontsize=7,color=COLORS['grey'])
# The interpretation is stated in the LaTeX caption, not inside the plot.
save(fig, 'fig1_benchmark_anatomy')
